// Service worker of forma, generated by scripts/build-sw.mjs after `vite build` (the lists below are filled in).
// It lets the installed app open without signal at the gym: the page and its code come from the device,
// and Firestore's own offline cache provides the data. Firebase and Google APIs are never intercepted.

const VERSION = "__VERSION__";
/** Code and styles of this build, saved on install so every screen opens offline, even one not visited yet. */
const PRECACHE = __PRECACHE__;
const SHELL = "/_shell.html";
const CACHE = `forma-${VERSION}`;
const RUNTIME = "forma-runtime";
// The home-screen icon and the manifest are left to the browser (never answered from here): Safari shows a blank
// letter instead of the icon on "Adicionar à Tela de Início" when they come from the service worker.
const STATIC_FILES = ["/favicon-32.png", "/icon-192.png"];
/** A slow connection waits this long for a fresh page before the saved one is used. */
const NETWORK_TIMEOUT_MS = 3500;

self.addEventListener("install", (event) => {
  event.waitUntil(
    (async () => {
      const cache = await caches.open(CACHE);
      // Hashed files that an earlier version already saved are copied instead of downloaded again.
      await Promise.all(
        [...PRECACHE, ...STATIC_FILES, SHELL].map(async (url) => {
          const saved = url.startsWith("/assets/") ? await caches.match(url) : undefined;
          const response = saved ?? (await fetch(new Request(url, { cache: "reload" })));
          if (!response.ok) throw new Error(`${url}: ${response.status}`);
          // Two installs at once (a second register, a quick reload) fill the same cache, and Chrome rejects a
          // put while the other one writes that URL; the file gets saved either way, so that must not fail the install.
          await cache.put(url, response).catch((error) => {
            if (error?.name !== "InvalidAccessError") throw error;
          });
        }),
      );
      await self.skipWaiting();
    })(),
  );
});

self.addEventListener("activate", (event) => {
  event.waitUntil(
    (async () => {
      for (const key of await caches.keys()) if (key !== CACHE && key !== RUNTIME) await caches.delete(key);
      await self.clients.claim();
    })(),
  );
});

/** Every route is the same single-page shell; the newest one is used when the network answers in time. */
async function page(request) {
  const cache = await caches.open(CACHE);
  const fresh = fetch(request).then(async (response) => {
    // A failed save (another write of the same file) must not fail the page itself.
    if (response.ok) await cache.put(SHELL, response.clone()).catch(() => undefined);
    return response;
  });
  const timeout = new Promise((resolve) => setTimeout(resolve, NETWORK_TIMEOUT_MS));
  try {
    const response = await Promise.race([fresh, timeout]);
    if (response) return response;
  } catch {
    // Offline: fall through to the saved page.
  }
  return (await cache.match(SHELL)) ?? fresh;
}

/** Hashed build files never change, so a saved copy is always right. */
async function asset(request) {
  const saved = await caches.match(request);
  if (saved) return saved;
  const response = await fetch(request);
  if (response.ok) await (await caches.open(RUNTIME)).put(request, response.clone());
  return response;
}

/** Icons, manifest and web fonts: answer from the device, refresh in the background. */
async function refreshing(request) {
  const cache = await caches.open(RUNTIME);
  const saved = await caches.match(request);
  const fresh = fetch(request)
    .then(async (response) => {
      // A failed save (another write of the same file) must not throw away the answer itself.
      if (response.ok || response.type === "opaque") await cache.put(request, response.clone()).catch(() => undefined);
      return response;
    })
    .catch(() => saved ?? Response.error());
  return saved ?? fresh;
}

self.addEventListener("fetch", (event) => {
  const request = event.request;
  if (request.method !== "GET") return;
  const url = new URL(request.url);
  if (request.mode === "navigate" && url.origin === self.location.origin) event.respondWith(page(request));
  else if (url.origin === self.location.origin && url.pathname.startsWith("/assets/")) event.respondWith(asset(request));
  else if (url.origin === self.location.origin && STATIC_FILES.includes(url.pathname)) event.respondWith(refreshing(request));
  else if (url.hostname === "fonts.googleapis.com" || url.hostname === "fonts.gstatic.com") event.respondWith(refreshing(request));
});

// Old runtime copies of images from earlier builds pile up; keep the runtime cache to a sane size.
const RUNTIME_LIMIT = 400;
self.addEventListener("message", (event) => {
  // Configurações shows which version this device runs.
  if (event.data === "version") return event.ports[0]?.postMessage({ version: VERSION });
  if (event.data !== "trim") return;
  event.waitUntil(
    (async () => {
      const cache = await caches.open(RUNTIME);
      const keys = await cache.keys();
      await Promise.all(keys.slice(0, Math.max(0, keys.length - RUNTIME_LIMIT)).map((key) => cache.delete(key)));
    })(),
  );
});

// Pushes from the Worker (strava-worker/src/notify.ts): the end of a rest and the daily reminder.
self.addEventListener("push", (event) => {
  let message = { title: "forma", body: "", tag: "forma", url: "/" };
  try {
    message = { ...message, ...event.data?.json() };
  } catch {
    // An empty or unreadable push still shows the generic notice: browsers require one per push.
  }
  event.waitUntil(
    (async () => {
      await self.registration.showNotification(message.title, {
        body: message.body,
        tag: message.tag,
        renotify: true,
        vibrate: [300, 150, 300],
        icon: "/icon-192.png",
        badge: "/icon-192.png",
        data: { url: message.url },
      });
      // End of a rest with the app on screen: the page already beeped, so the notice is taken away at once.
      // It is still shown first, since iOS cancels the subscription of an app that receives pushes without showing them.
      if (message.tag !== "forma-descanso") return;
      const windows = await self.clients.matchAll({ type: "window", includeUncontrolled: true });
      if (!windows.some((client) => client.visibilityState === "visible")) return;
      await new Promise((resolve) => setTimeout(resolve, 300));
      for (const notice of await self.registration.getNotifications({ tag: "forma-descanso" })) notice.close();
    })(),
  );
});

// Tapping a notification brings the app back (to the workout for a rest, to Hoje for the reminder).
self.addEventListener("notificationclick", (event) => {
  event.notification.close();
  const url = event.notification.data?.url ?? "/treinos";
  event.waitUntil(
    (async () => {
      const windows = await self.clients.matchAll({ type: "window", includeUncontrolled: true });
      const open = windows.find((client) => new URL(client.url).origin === self.location.origin);
      if (open) {
        await open.focus();
        if (new URL(open.url).pathname !== url) await open.navigate(url).catch(() => undefined);
      } else await self.clients.openWindow(url);
    })(),
  );
});
